<script lang="ts">
  import { allEntries } from "$lib/content/data";
  import type { EntryKind } from "$lib/content/types";
  type KindFilter = "all";
  const kindFilters: { label: string; value: KindFilter }[] = [{ label: "Dictionary", value: "all" }];
  const routeBase: Record<EntryKind, string> = { grammar: "grammar", pronunciation: "pronunciation", word: "dictionary" };
  const categoryCounts = new Map<string, number>();
  const dictionaryEntries = allEntries.filter((entry) => entry.kind === "word");
  for (const entry of dictionaryEntries) categoryCounts.set(entry.category, (categoryCounts.get(entry.category) ?? 0) + 1);
  const categories = [...categoryCounts].toSorted(([first], [second]) => first.localeCompare(second));
  const normalize = (value: string): string => value.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLocaleLowerCase();
  const filterClass = (active: boolean): string => active ? "bg-blue-600 text-white" : "bg-transparent text-slate-600 hover:bg-slate-100";
  let activeKind = $state<KindFilter>("all"); let activeCategory = $state("all"); let activeLetter = $state("all"); let query = $state("");
  let kindEntries = $derived(dictionaryEntries);
  let availableLetters = $derived([...new Set(kindEntries.map((entry) => entry.slovak.at(0)?.toLocaleUpperCase("sk") ?? "#"))].toSorted((first, second) => first.localeCompare(second, "sk")));
  let visibleEntries = $derived(kindEntries.filter((entry) => activeCategory === "all" || entry.category === activeCategory).filter((entry) => activeLetter === "all" || entry.slovak.at(0)?.toLocaleUpperCase("sk") === activeLetter).filter((entry) => { const needle = normalize(query.trim()); return !needle || normalize(`${entry.slovak} ${entry.english} ${entry.category} ${entry.tags.join(" ")}`).includes(needle); }).toSorted((first, second) => first.slovak.localeCompare(second.slovak, "sk")));
  function clearFilters(): void { activeKind = "all"; activeCategory = "all"; activeLetter = "all"; query = ""; }
  function selectKind(kind: KindFilter): void { activeKind = kind; activeCategory = "all"; activeLetter = "all"; }
</script>

<svelte:head><title>Slovak Wiki — Slovak language reference and lessons</title><meta name="description" content="Search Slovak words, grammar notes, and pronunciation guides."></svelte:head>

<main class="min-h-[calc(100vh-58px)]"><div class="grid grid-cols-[215px_minmax(0,1fr)_205px] max-[1100px]:grid-cols-[215px_minmax(0,1fr)] max-[760px]:block">
  <aside class="sticky top-[var(--header-height)] h-[calc(100vh-var(--header-height)-28px)] overflow-y-auto border-r border-slate-200 px-5 pb-12 pt-7 max-[760px]:hidden"><div class="mb-8 flex items-baseline justify-between"><strong class="font-serif text-base text-slate-900">Slovak Wiki</strong><span class="text-xs text-slate-500">{dictionaryEntries.length} words</span></div><nav class="grid gap-1" aria-label="Content type"><p class="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">Browse</p>{#each kindFilters as filter (filter.value)}<button class={`flex min-h-9 w-full cursor-pointer items-center justify-between rounded px-2 py-1.5 text-left text-sm ${filterClass(activeKind === filter.value)}`} aria-pressed={activeKind === filter.value} type="button" onclick={() => selectKind(filter.value)}><span>{filter.label}</span><small>{dictionaryEntries.length}</small></button>{/each}</nav><nav class="mt-8 grid gap-1" aria-label="Reference sections"><p class="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">Reference sections</p><a class="grid gap-1 border-l-2 border-slate-200 px-2 py-2 font-serif text-sm text-blue-800 hover:border-blue-600 hover:bg-blue-50" href="/grammar"><strong>Grammar</strong><span class="text-xs text-slate-500">Rules and patterns →</span></a><a class="grid gap-1 border-l-2 border-slate-200 px-2 py-2 font-serif text-sm text-blue-800 hover:border-blue-600 hover:bg-blue-50" href="/pronunciation"><strong>Pronunciation</strong><span class="text-xs text-slate-500">Sounds and spelling →</span></a></nav><nav class="mt-8 grid gap-1" aria-label="Topics"><p class="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">Topics</p><button class={`flex min-h-9 w-full cursor-pointer items-center justify-between rounded px-2 py-1.5 text-left text-sm ${filterClass(activeCategory === "all")}`} aria-pressed={activeCategory === "all"} type="button" onclick={() => (activeCategory = "all")}>All topics</button>{#each categories as [category, count] (category)}<button class={`flex min-h-9 w-full cursor-pointer items-center justify-between rounded px-2 py-1.5 text-left text-sm ${filterClass(activeCategory === category)}`} aria-pressed={activeCategory === category} type="button" onclick={() => (activeCategory = category)}><span>{category}</span><small>{count}</small></button>{/each}</nav></aside>
  <section class="min-w-0 px-8 py-9 pb-20 max-[760px]:px-3.5 max-[760px]:py-8" aria-label="Dictionary results"><header class="pb-8"><p class="mb-4 text-xs font-semibold uppercase tracking-wide text-blue-700">Reference / Dictionary</p><h1 class="text-5xl">Dictionary</h1><p class="mt-3 font-serif text-sm text-slate-600">Look up Slovak words by topic, letter, or English meaning.</p></header><div id="wiki-search-section" class="mb-6"><label class="mb-2 block text-sm font-semibold text-slate-700" for="wiki-search">Search dictionary words</label><div class="flex h-11 items-center border border-slate-300 bg-white focus-within:border-blue-600 focus-within:ring-2 focus-within:ring-blue-100"><svg class="ml-3 w-4 fill-none stroke-slate-400" aria-hidden="true" viewBox="0 0 24 24"><path d="m21 21-4.35-4.35m2.35-5.15a7.5 7.5 0 1 1-15 0 7.5 7.5 0 0 1 15 0Z" /></svg><input class="min-w-0 flex-1 border-0 bg-transparent px-3 text-sm outline-0" id="wiki-search" bind:value={query} placeholder="Search in English or Slovak" type="search">{#if query}<button class="mr-3 cursor-pointer border-0 bg-transparent text-xs font-semibold text-blue-700" type="button" aria-label="Clear search" onclick={() => (query = "")}>Clear</button>{/if}</div></div><nav class="mb-4 hidden gap-1 overflow-x-auto max-[760px]:flex" aria-label="Dictionary type">{#each kindFilters as filter (filter.value)}<button class={`shrink-0 rounded border border-slate-200 px-2.5 py-2 text-xs ${filterClass(activeKind === filter.value)}`} aria-pressed={activeKind === filter.value} type="button" onclick={() => selectKind(filter.value)}>{filter.label}</button>{/each}</nav><nav class="mb-4 hidden gap-1 overflow-x-auto max-[760px]:flex" aria-label="Reference sections"><a class="shrink-0 rounded border border-slate-200 px-2.5 py-2 text-xs text-blue-800" href="/grammar">Grammar</a><a class="shrink-0 rounded border border-slate-200 px-2.5 py-2 text-xs text-blue-800" href="/pronunciation">Pronunciation</a></nav><nav class="mb-4 hidden gap-1 overflow-x-auto max-[760px]:flex" aria-label="Topics"><button class={`shrink-0 rounded border border-slate-200 px-2.5 py-2 text-xs ${filterClass(activeCategory === "all")}`} type="button" onclick={() => (activeCategory = "all")}>All topics</button>{#each categories as [category] (category)}<button class={`shrink-0 rounded border border-slate-200 px-2.5 py-2 text-xs ${filterClass(activeCategory === category)}`} type="button" onclick={() => (activeCategory = category)}>{category}</button>{/each}</nav><nav id="wiki-alphabet" class="flex gap-0.5 overflow-x-auto border-b border-slate-200 pb-4" aria-label="Filter by first letter"><button class={`h-8 min-w-8 rounded px-2 text-xs font-semibold ${filterClass(activeLetter === "all")}`} aria-pressed={activeLetter === "all"} type="button" onclick={() => (activeLetter = "all")}>All</button>{#each availableLetters as letter (letter)}<button class={`h-8 min-w-8 rounded px-2 text-xs font-semibold ${filterClass(activeLetter === letter)}`} aria-pressed={activeLetter === letter} type="button" onclick={() => (activeLetter = letter)}>{letter}</button>{/each}</nav><div class="flex min-h-12 items-center justify-between"><p class="m-0 text-xs text-slate-500"><strong class="mr-1 text-slate-900">{visibleEntries.length}</strong>{visibleEntries.length === 1 ? "result" : "results"}</p>{#if activeKind !== "all" || activeCategory !== "all" || activeLetter !== "all" || query}<button class="cursor-pointer border-0 bg-transparent text-xs font-semibold text-blue-700" type="button" onclick={clearFilters}>Reset filters</button>{/if}</div><div class="grid grid-cols-[minmax(160px,.8fr)_minmax(220px,1.25fr)_150px_24px] items-center gap-6 border border-slate-200 bg-slate-50 px-3.5 text-xs font-bold uppercase tracking-wide text-slate-500 max-[760px]:hidden"><span>Slovak</span><span>English</span><span>Type</span></div>{#if visibleEntries.length}<div id="wiki-results" class="border border-t-0 border-slate-200 bg-white max-[760px]:border-t">{#each visibleEntries as entry (entry.slug)}<a class="grid min-h-14 grid-cols-[minmax(160px,.8fr)_minmax(220px,1.25fr)_150px_24px] items-center gap-6 border-b border-slate-200 px-3.5 py-2.5 hover:bg-slate-50 max-[760px]:grid-cols-[minmax(0,1fr)_18px] max-[760px]:gap-1.5" href="/{routeBase[entry.kind]}/{entry.slug}"><span class="font-semibold text-blue-700 max-[760px]:col-start-1" lang="sk">{entry.slovak}</span><span class="text-sm text-slate-900 max-[760px]:col-start-1">{entry.english}</span><span class="text-xs capitalize text-slate-500 max-[760px]:hidden">{entry.kind === "word" ? entry.category : entry.kind}</span><svg class="w-4 fill-none stroke-slate-400 max-[760px]:col-start-2 max-[760px]:row-span-2" aria-hidden="true" viewBox="0 0 24 24"><path d="m9 18 6-6-6-6" /></svg></a>{/each}</div>{:else}<div class="border border-t-0 border-slate-200 px-6 py-[72px] text-center"><h2 class="text-base">No matches</h2><p class="text-sm text-slate-500">Try a shorter search or reset the filters.</p><button class="rounded border border-slate-300 bg-white px-3 py-2 text-xs font-semibold text-blue-700" type="button" onclick={clearFilters}>Show all entries</button></div>{/if}</section>
  <aside class="context-rail sticky top-[var(--header-height)] h-fit border-l border-slate-200 px-4 py-8 pb-12 max-[1100px]:col-start-2 max-[1100px]:grid max-[1100px]:grid-cols-3 max-[1100px]:gap-6 max-[1100px]:border-l-0 max-[1100px]:border-t max-[1100px]:px-8 max-[1100px]:py-6 max-[760px]:static max-[760px]:grid-cols-1 max-[760px]:gap-6 max-[760px]:px-3.5" aria-label="Wiki context"><section><p class="rail-label">On this page</p><nav class="grid border-l-2 border-slate-200"><a class="py-1.5 pl-2.5 font-serif text-sm text-blue-800" href="#wiki-search-section">Search</a><a class="py-1.5 pl-2.5 font-serif text-sm text-blue-800" href="#wiki-alphabet">Alphabet</a><a class="py-1.5 pl-2.5 font-serif text-sm text-blue-800" href="#wiki-results">Entries</a></nav></section><section><p class="rail-label">Current view</p><dl class="grid gap-3"><div><dt class="text-xs uppercase text-slate-500">Reference</dt><dd class="font-serif text-sm text-slate-700">Dictionary</dd></div><div><dt class="text-xs uppercase text-slate-500">Topic</dt><dd class="font-serif text-sm text-slate-700">{activeCategory === "all" ? "All topics" : activeCategory}</dd></div><div><dt class="text-xs uppercase text-slate-500">Letter</dt><dd class="font-serif text-sm text-slate-700">{activeLetter === "all" ? "Any" : activeLetter}</dd></div></dl></section><section><p class="rail-label">Continue</p><nav class="grid"><a class="py-1.5 font-serif text-sm text-blue-800 hover:underline" href="/grammar">Grammar</a><a class="py-1.5 font-serif text-sm text-blue-800 hover:underline" href="/pronunciation">Pronunciation</a><a class="py-1.5 font-serif text-sm text-blue-800 hover:underline" href="/lessons">Lessons</a><a class="py-1.5 font-serif text-sm text-blue-800 hover:underline" href="/practice">Practice</a></nav></section></aside>
</div></main>
